INSERT INTO Service VALUES('landscape-design-consultation','Landscape Design Consultation','Consulta de Diseño Paisajístico','Personalized 1-hour consultation with Maytee to design your dream garden. Includes a written plan and plant list tailored to your space and Miami''s climate.','Consulta personalizada de 1 hora con Maytee para diseñar el jardín de sus sueños. Incluye un plan escrito y lista de plantas adaptada a su espacio y el clima de Miami.',150.0,'Starting at $150/hr','https://images.unsplash.com/photo-1416879595882-3373a0480b5b?auto=format&fit=crop&w=800&q=80',60,1,1779741584589);
INSERT INTO Service VALUES('garden-installation','Garden Installation','Instalación de Jardín','Full installation of your new garden design. We source, deliver, and plant everything — from tropical specimens to flowering borders. Pricing based on project scope.','Instalación completa de su nuevo diseño de jardín. Conseguimos, entregamos y plantamos todo — desde especímenes tropicales hasta bordes florales.',NULL,'Custom quote — contact us','https://images.unsplash.com/photo-1558618666-fcd25c85cd64?auto=format&fit=crop&w=800&q=80',240,1,1779741584590);
INSERT INTO Service VALUES('plant-rescue-&-restoration','Plant Rescue & Restoration','Rescate y Restauración de Plantas','Maytee''s signature service: we evaluate your existing plants before removing anything. Save what can be saved, transform what needs a boost.','El servicio estrella de Maytee: evaluamos sus plantas existentes antes de remover nada. Salvamos lo que se puede salvar, transformamos lo que necesita un impulso.',200.0,'Starting at $200 per visit','https://images.unsplash.com/photo-1466692476868-aef1dfb1e735?auto=format&fit=crop&w=800&q=80',120,1,1779741584592);
INSERT INTO Service VALUES('ongoing-garden-maintenance','Ongoing Garden Maintenance','Mantenimiento de Jardín','Monthly maintenance visits to keep your garden thriving in South Florida''s unique climate. Includes pruning, fertilizing, pest management, and seasonal adjustments.','Visitas mensuales de mantenimiento para mantener su jardín floreciente en el clima único del sur de Florida.',180.0,'$180–$350/month depending on size','https://images.unsplash.com/photo-1585320806297-9794b3e4aaae?auto=format&fit=crop&w=800&q=80',90,1,1779741584594);
INSERT INTO Plant VALUES('cmplo6rir0003fjdmor4amkjh','Bougainvillea','Buganvilla','Bougainvillea is a genus of thorny ornamental vines, bushes, and trees belonging to the family Nyctaginaceae. They are native to the tropical forests of South America. There are between 4 and 22 species in the genus. The inflorescence consists of large colorful sepal-like bracts which surround three simple waxy flowers, gaining popularity for the plant as an ornamental. The plant is named after explorer Louis Antoine de Bougainville (1729–1811), ','Bougainvillea is a genus of thorny ornamental vines, bushes, and trees belonging to the family Nyctaginaceae. They are native to the tropical forests of South America. There are between 4 and 22 species in the genus. The inflorescence consists of large colorful sepal-like bracts which surround three simple waxy flowers, gaining popularity for the plant as an ornamental. The plant is named after explorer Louis Antoine de Bougainville (1729–1811), ',35.0,'https://upload.wikimedia.org/wikipedia/commons/4/4c/Bougainvillea_closeup.jpg','flowering',1,10,1,'climber,fence,colorful,drought-tolerant','easy','full','low',1779741584596,1780016063163);
INSERT INTO Plant VALUES('cmplo6rit0004fjdmzrwqktsw','Bird of Paradise','Ave del Paraíso','Strelitzia reginae, commonly known as the crane flower, bird of paradise, or isigude in Nguni, is a species of flowering plant native to the Cape Provinces and KwaZulu-Natal in South Africa. An evergreen perennial, it is widely cultivated for its dramatic flowers. In temperate areas it is a popular houseplant.','Strelitzia reginae, llamada popularmente ave del paraíso, es una especie herbácea originaria de Sudáfrica. Se cultiva extensamente como planta ornamental por la forma peculiar de su flor.',65.0,'https://upload.wikimedia.org/wikipedia/commons/9/97/Ave-do-para%C3%ADso%2C_Strelitzia_reginae%2C_em_Bag%C3%A9%2C_Rio_Grande_do_Sul%2C_Brasil_-_55211233712.jpg','tropical',1,10,1,'architectural,focal-point,tropical','easy','full','moderate',1779741584597,1780016063165);
INSERT INTO Plant VALUES('cmplo6riu0005fjdmjcvy7t51','Areca Palm','Palma Areca','Chrysalidocarpus lutescens, also known by its synonym Dypsis lutescens and as golden cane palm, areca palm, yellow palm, butterfly palm, or bamboo palm, is a species of flowering plant in the family Arecaceae, native to Madagascar and naturalized in the Andaman Islands, Thailand, Vietnam, Réunion, El Salvador, Cuba, Puerto Rico, the Canary Islands, southern Florida, Haiti, the Dominican Republic, Jamaica, the Leeward Islands, and the Leeward Anti','Dypsis lutescens es una especie tropical de palmera originaria de Madagascar y utilizada como planta ornamental.',89.0,'https://upload.wikimedia.org/wikipedia/commons/2/22/%E6%95%A3%E5%B0%BE%E8%91%B5Dypsis_lutescens_20210511145013_05.jpg','palms',1,10,1,'privacy,pool,tropical,fast-growing','easy','partial','moderate',1779741584598,1780016063167);
INSERT INTO Plant VALUES('cmplo6riv0006fjdmemg72jw0','Ixora','Ixora','Ixora coccinea is a species of flowering plant in the family Rubiaceae. It is a common flowering shrub native to Southern India, Bangladesh, and Sri Lanka. It has become one of the most popular flowering shrubs in South Florida gardens and landscapes. It is the national flower of Suriname.','Ixora coccinea, conocida como geranio de la jungla, llama de los bosques, coral, Cruz de Malta, coral de México y llama de la jungla, es una especie de arbusto perteneciente a la familia de las rubiáceas. Es la flor oficial de la ciudad de Cúcuta, en Colombia.',22.0,'https://upload.wikimedia.org/wikipedia/commons/7/77/Ixora_coccinea.jpg','flowering',1,10,1,'hedge,colorful,butterfly,year-round','easy','full','moderate',1779741584600,1780016063169);
INSERT INTO Plant VALUES('cmplo6riw0007fjdmea43w005','Dwarf Olive Tree','Olivo Enano','The olive is a species of subtropical evergreen tree in the family Oleaceae. Originating in Asia Minor, it is abundant throughout the Mediterranean Basin, with wild subspecies in Africa and western Asia; modern cultivars are traced primarily to the Near East, Aegean Sea, and Strait of Gibraltar. The olive is the type species for its genus, Olea, and lends its name to the Oleaceae plant family, which includes lilac, jasmine, forsythia, and ash. Th','Olea europaea, llamado comúnmente olivo y olivera, así como también oliva y aceituno, es un árbol pequeño perennifolio que puede alcanzar hasta 15 m de altura, con tronco grueso de aspecto retorcido. Su corteza es de color gris o plateado y tiene hojas opuestas, lanceoladas. Las flores son hermafroditas, en panículas axilares multifloras, con corola blanca. El fruto, la aceituna u oliva, es una drupa de 1 a 3,5 cm de largo. Su periodo de floració',95.0,'https://upload.wikimedia.org/wikipedia/commons/8/84/Olivesfromjordan.jpg','tropical',1,10,1,'container,mediterranean,patio,elegant','moderate','full','low',1779741584601,1780016063170);
INSERT INTO Plant VALUES('cmplo6riz0008fjdmwlk4f9mx','Firebush','Arbusto de Fuego','Hamelia patens is a large evergreen perennial shrub or small tree in the family	Rubiaceae, that is native to the American subtropics and tropics. Its range extends from Florida in the southern United States to as far south as Argentina. Common names include firebush, hummingbird bush, scarlet bush, and redhead. In Belize, this plant''s Mayan name is Ix Canaan and is also known as "Guardian of the Forest".','Hamelia patens es una especie de arbusto grande, perenne, de América subtropical y tropical de la familia de las rubiáceas. Se encuentra desde Florida en el sur de Estados Unidos a Argentina. Tiene flores tubulares anaranjadas rojas, agradables para colibríes y mariposas para polinizar.',18.0,'https://upload.wikimedia.org/wikipedia/commons/8/8e/Bencenuco_%28Hamelia_patens%29_-_Flickr_-_Alejandro_Bayer_%282%29.jpg','native',1,10,1,'native,butterfly,hummingbird,drought-tolerant','easy','full','low',1779741584603,1780016063172);
INSERT INTO Plant VALUES('cmplo6rj10009fjdm1r0lkems','Croton','Croton','Croton thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Croton prospera en el cálido y húmedo clima del sur de Florida.',28.0,'https://upload.wikimedia.org/wikipedia/commons/b/bf/Colpfl05.jpg','tropical',1,10,1,'colorful,tropical,bold,container','easy','partial','moderate',1779741584605,1780016063173);
INSERT INTO Plant VALUES('cmplo6rj4000afjdmm11uszeh','Plumbago','Plumbago','Plumbago auriculata, the Cape leadwort, blue plumbago or Cape plumbago, is a species of flowering plant in the family Plumbaginaceae, native to South Africa and Mozambique.','Plumbago auriculata, the Cape leadwort, blue plumbago or Cape plumbago, is a species of flowering plant in the family Plumbaginaceae, native to South Africa and Mozambique.',20.0,'https://upload.wikimedia.org/wikipedia/commons/e/e1/Plumbago_auriculata_2718.jpg','flowering',1,10,1,'hedge,blue,butterfly,year-round','easy','full','moderate',1779741584608,1780016063175);
INSERT INTO Plant VALUES('cmplo6rj9000cfjdmeorhmkga','Lantana','Lantana','Lantana camara is a species of flowering plant in the verbena family (Verbenaceae), native to the tropics of the Americas. It is a very adaptable species, which can inhabit a wide variety of ecosystems; once it has been introduced into a habitat it spreads rapidly; between 45ºN and 45ºS and less than 1,400 metres in altitude.','Lantana camara is a species of flowering plant in the verbena family (Verbenaceae), native to the tropics of the Americas. It is a very adaptable species, which can inhabit a wide variety of ecosystems; once it has been introduced into a habitat it spreads rapidly; between 45ºN and 45ºS and less than 1,400 metres in altitude.',16.0,'https://upload.wikimedia.org/wikipedia/commons/5/52/LantanaFlowerLeaves.jpg','flowering',1,10,0,'butterfly,border,colorful,fast-growing','easy','full','low',1779741584613,1780016063177);
INSERT INTO Plant VALUES('cmplo6rjb000dfjdmk7qf6ahf','Star Jasmine','Jazmín de Estrella','Trachelospermum jasminoides is a species of flowering plant in the family Apocynaceae, native to eastern and southeastern Asia. Common names include Confederate jasmine, star jasmine, Confederate jessamine, and Chinese star jessamine.','Trachelospermum jasminoides, llamada popularmente jazmín estrella, jazmin campanita, jazmín hélice, jazmin del aire o jazmín de leche, es una especie trepadora perteneciente al género Trachelospermum.',28.0,'https://upload.wikimedia.org/wikipedia/commons/9/92/Trachelospermum_jasminoides1215878198.jpg','flowering',1,10,0,'fragrant,climber,fence,pergola','easy','partial','moderate',1779741584615,1780016063179);
INSERT INTO Plant VALUES('cmplo6rjf000efjdmt9zkcp9n','Traveler''s Palm','Palma del Viajero','Ravenala madagascariensis, commonly known as the traveller''s tree, fan palm, traveller''s palm or East-West palm, is a species of monocotyledonous flowering plant found in Madagascar. It is not a true palm but a member of the family Strelitziaceae. In tropical and subtropical regions, the plant is widely cultivated for its distinctive habit and foliage.','Ravenala madagascariensis, llamada comúnmente árbol del viajero o palma del viajero es la única especie del género monotípico Ravenala. Forma parte de la familia Strelitziaceae y está estrechamente emparentado con el ave del paraíso. Es endémica de Madagascar donde habita renovales.',145.0,'https://upload.wikimedia.org/wikipedia/commons/a/a4/Ravenala%2C_travellers_palms%2C_on_Maui.jpg','palms',1,10,1,'statement,tropical,architectural','easy','full','moderate',1779741584619,1780016063180);
INSERT INTO Plant VALUES('cmpq6psga0000k6o6gi538b2l','Bismarck Palm','Palma Bismarck','Bismarckia is a monotypic genus of flowering plant in the palm family with Bismarckia nobilis being the only species in the genus and is endemic to western and northern Madagascar, where it grows in open grassland.','Bismarckia es un género monotípico con una única especie: Bismarckia nobilis, la palmera de Bismarck, o palmera azul de Madagascar, perteneciente a la familia de las palmeras (Arecaceae).',199.0,'https://upload.wikimedia.org/wikipedia/commons/f/f9/B.nobilis.JPG','palms',1,10,0,'statement,silver,large','easy','full','low',1780014570059,1780016063181);
INSERT INTO Plant VALUES('cmpq6psx20001k6o61t1vtdok','Christmas Palm','Palma Navideña','Adonidia merrillii, the Manila palm, is a palm tree species endemic to the Philippines. This palm was cultivated for centuries in the Philippines before becoming a staple in the West. It is reportedly naturalized in the West Indies and Florida. It is commonly known as the "Christmas palm" because its fruits become bright scarlet and tend to be that color in winter. This palm is typically fairly small and slender, normally attaining 25 feet or 8 m','Adonidia merrillii es una especie de palmera de la familia Arecaceae. Se la conoce comúnmente como palma de Manila, palmera kerpis, chaguaramo enano o palma de Navidad por su fruto rojo que madura en invierno. Es una palmera endémica de Filipinas y especial de la isla de Palawan y también en la Isla de Borneo.',120.0,'https://upload.wikimedia.org/wikipedia/commons/9/9d/Adonidia_merrillii_Vi%C3%B1ales_Cuba_3.jpg','palms',1,10,0,'elegant,compact,landscape','easy','full','moderate',1780014570663,1780016063183);
INSERT INTO Plant VALUES('cmpq6pt9g0002k6o6qn0gmnk4','Coconut Palm','Palma de Coco','The coconut is a member of the palm family (Arecaceae) and the only living species of the genus Cocos. The term "coconut" can denote the whole coconut palm tree or the large hard fruit. Originally native to the Central Indo-Pacific, they are ubiquitous in coastal tropical regions.','Cocos nucifera llamado comúnmente cocotero o simplemente coco es una especie de palmera de la familia Arecaceae. Es monotípica, y su única especie es Cocos nucifera. Este género tuvo muchas especies que se fueron independizando de él, algunas hacia el género Syagrus. Taxonómicamente hablando, las especies más próximas son Jubaeopsis caffra de Sudáfrica y Voanioala gerardii de Madagascar. El árbol es cultivado desde hace siglos como planta ornamen',149.0,'https://upload.wikimedia.org/wikipedia/commons/3/32/Cocos_nucifera_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-187.jpg','palms',1,10,1,'tropical,beach,iconic,edible','easy','full','moderate',1780014571108,1780016063185);
INSERT INTO Plant VALUES('cmpq6ptm60003k6o6z5n4xji1','Fishtail Palm','Palma Cola de Pez','Caryota mitis, known as the clustering fishtail palm or fishtail palm, is a species of palm native to Tropical Asia from India to Java to southern China, now sparingly naturalized in southern Florida and in parts of Africa and Latin America. The species was originally described from Vietnam in 1790. In Florida, it grows in hummocks and in disturbed wooded areas.','Caryota mitis es una palmera originaria del sureste de Asia, posee varios estípites o tallos bastante delgados de hasta 12 m de altura, es una palma sin capitel. Cada tronco muere al florecer, sin embargo, nacen otros nuevos, es de crecimiento bastante rápido. Se ha mostrado sensible a la enfermedad denominada Lethal Yellowing o amarilleo letal, resisten trasplante.',129.0,'https://upload.wikimedia.org/wikipedia/commons/9/99/Caryota_mitis_leaves.jpg','palms',1,10,0,'unique,tropical,cluster','moderate','partial','moderate',1780014571567,1780016063187);
INSERT INTO Plant VALUES('cmpq6pu3q0004k6o69ppheaas','Foxtail Palm','Palma Cola de Zorro','Wodyetia is a genus of the palm family Arecaceae, containing the single species Wodyetia bifurcata. The species, commonly known as foxtail palm, is native to a very small area of northeastern Queensland, Australia, but has been widely cultivated around the world.','Wodyetia bifurcata Irvine es una especie de palmera de la familia Arecaceae. Es la única especie del género Wodyetia.',149.0,'https://upload.wikimedia.org/wikipedia/commons/6/63/FoxTail_Palm_at_Seaworld.jpg','palms',1,10,0,'elegant,fast-growing,landscape','easy','full','moderate',1780014572198,1780016063189);
INSERT INTO Plant VALUES('cmpq6puga0005k6o6n7ad8gnf','Mexican Fan Palm','Palma Abanico Mexicana','Washingtonia filifera var. robusta, commonly known as the Mexican fan palm, Mexican washingtonia, or skyduster, is a flowering plant in the family Arecaceae native to the Sonoran desert along the Baja California peninsula. Despite its limited native distribution, W. filifera var. robusta is one of the most widely cultivated subtropical palms in the world. It is naturalized across the southern United States, Mediterranean, and Middle East.','La palmera de abanico mexicana es una especie de planta perteneciente a la familia Arecaceae.',75.0,'https://upload.wikimedia.org/wikipedia/commons/b/b8/Arecales_-_Washingtonia_robusta_-_1.jpg','palms',1,10,0,'tall,drought-tolerant,urban','easy','full','low',1780014572651,1780016063191);
INSERT INTO Plant VALUES('cmpq6puzx0006k6o6sj688flb','Queen Palm','Palma Reina','Syagrus romanzoffiana, the queen palm, cocos palm or Jerivá, is a palm native to South America, introduced throughout the world as a popular ornamental garden tree. S. romanzoffiana is a medium-sized palm, quickly reaching maturity at a height of up to 15 m (49 ft) tall, with pinnate leaves having as many as 494 pinnae (leaflets), although more typically around 300, each pinna being around 50 centimetres (18 in) in length and 3–5 centimetres (1–2','La palmera pindó o ybá pitá, también Mbokaja aka en guaraní, es una especie de la familia de las palmeras (Arecaceae). Es nativa del sur de Brasil, Paraguay, Uruguay, y el Litoral argentino.',129.0,'https://upload.wikimedia.org/wikipedia/commons/5/5d/Jeriv%C3%A1_%28do_tupi_iara%27yb%C3%A1%29_com_frutos_ainda_verdes_06.jpg','palms',1,10,0,'graceful,feathery,pool','easy','full','moderate',1780014573358,1780016063192);
INSERT INTO Plant VALUES('cmpq6pvj70007k6o62abf6aka','Royal Palm','Palma Real','Roystonea regia, commonly known as the royal palm, Cuban royal palm, or Florida royal palm, is a species of palm native to Mexico, the Caribbean, Florida, and parts of Central America. A large and attractive palm, it has been planted throughout the tropics and subtropics as an ornamental tree. Although it is sometimes called R. elata, the conserved name R. regia is now the correct name for the species. The royal palm reaches heights from 15–24 m ','Roystonea regia, conocida como palma real, es una especie de palma cuya altura, elegancia y fácil cultivo la ha convertido en una de los árboles utilizados como ornamental más común en el mundo. Es también el más simbólico de los campos de Cuba, donde es reconocido como árbol nacional. El epíteto específico «regia» viene del latín rēgia y significa "real".',175.0,'https://upload.wikimedia.org/wikipedia/commons/3/3e/Roystonea_regia.jpg','palms',1,10,1,'majestic,formal,iconic','easy','full','moderate',1780014574051,1780016063194);
INSERT INTO Plant VALUES('cmpq6pw3y0008k6o6qi7ya5j5','Sabal Palm','Palma Sabal','Sabal palmetto, also known as cabbage palm, cabbage palmetto, sabal palm, palmetto palm, blue palmetto, Carolina palmetto, common palmetto, and swamp cabbage, is one of 15 species of palmetto palm.','La palma de abanico o palmito de tierra firme es una especie de planta con flor, de las 15 especies de arecáceas del género Sabal.',89.0,'https://upload.wikimedia.org/wikipedia/commons/2/2a/Spalmetto2.JPG','palms',1,10,0,'native,drought-tolerant,florida','easy','full','low',1780014574798,1780016063196);
INSERT INTO Plant VALUES('cmpq6pwgd0009k6o6kikv0zry','Sago Palm','Palma Sagú','Cycas revoluta is a species of gymnosperm in the family Cycadaceae, native to southern Japan including the Ryukyu Islands. It is one of several species used for the production of sago, as well as an ornamental plant. The sago cycad can be distinguished by a thick coat of fibers on its trunk. The sago cycad is sometimes mistakenly thought to be a palm, although the only similarity between the two is that they look similar and both produce seeds.','Cycas revoluta es una planta cicadácea oriunda del sur de Japón.',95.0,'https://upload.wikimedia.org/wikipedia/commons/3/3b/Cycas_inflorescence.jpg','palms',1,10,0,'ancient,sculptural,slow-growing','moderate','full','low',1780014575245,1780016063197);
INSERT INTO Plant VALUES('cmpq6px6z000ak6o640054901','Washingtonia Palm','Palma Washingtonia','Washingtonia Palm thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Palma Washingtonia prospera en el cálido y húmedo clima del sur de Florida.',85.0,'https://upload.wikimedia.org/wikipedia/commons/b/b8/Washingtonia_filifera.jpg','palms',1,10,0,'tall,drought-tolerant','easy','full','low',1780014576203,1780016063199);
INSERT INTO Plant VALUES('cmpq6pxk1000bk6o6f1qzh6c1','Windmill Palm','Palma Molino de Viento','Trachycarpus fortunei, also known as the Chusan palm, Chinese windmill palm, hemp palm, or simply windmill palm, is a species of hardy evergreen palm tree in the family Arecaceae, native to parts of China, Japan, Myanmar and India.','Trachycarpus fortunei, also known as the Chusan palm, Chinese windmill palm, hemp palm, or simply windmill palm, is a species of hardy evergreen palm tree in the family Arecaceae, native to parts of China, Japan, Myanmar and India.',99.0,'https://upload.wikimedia.org/wikipedia/commons/c/c2/TrachycarpusFortunei.jpg','palms',1,10,0,'cold-hardy,compact','moderate','partial','moderate',1780014576673,1780016063200);
INSERT INTO Plant VALUES('cmpq6pxw2000ck6o6i2vxa93j','African Iris','Iris Africano','Dietes iridioides, commonly named African iris, fortnight lily, and morea iris, is a species of plant in the family Iridaceae that is native to Southern Africa.','Dietes iridioides, commonly named African iris, fortnight lily, and morea iris, is a species of plant in the family Iridaceae that is native to Southern Africa.',22.0,'https://upload.wikimedia.org/wikipedia/commons/4/46/Fortnight_Lily_flower.jpg','flowering',1,10,0,'border,drought-tolerant,white','easy','full','low',1780014577107,1780016063201);
INSERT INTO Plant VALUES('cmpq6py84000dk6o662cz8npl','Bauhinia','Árbol de Orquídea','Bauhinia purpurea is a species of flowering plant in the family Fabaceae, native to the Indian subcontinent and Myanmar, and widely introduced elsewhere in tropical and subtropical areas of the world. Common names include orchid tree, purple bauhinia, camel''s foot, butterfly tree, and Hawaiian orchid tree.','Bauhinia purpurea is a species of flowering plant in the family Fabaceae, native to the Indian subcontinent and Myanmar, and widely introduced elsewhere in tropical and subtropical areas of the world. Common names include orchid tree, purple bauhinia, camel''s foot, butterfly tree, and Hawaiian orchid tree.',65.0,'https://upload.wikimedia.org/wikipedia/commons/8/8e/Phanera_purpurea_tree_with_fruits_%28Philippines%29.jpg','flowering',1,10,0,'tree,orchid-like,pink,butterfly','easy','full','moderate',1780014577541,1780016063203);
INSERT INTO Plant VALUES('cmpq6pyk9000ek6o6x92iimc3','Blue Daze','Rocío Azul','Evolvulus glomeratus, commonly known as blue daze, Brazilian dwarf morning-glory, or Hawaiian blue eyes, is flowering plant from the family Convolvulaceae that is native to Brazil, Guyana, Bolivia and Venezuela.','Evolvulus glomeratus, commonly known as blue daze, Brazilian dwarf morning-glory, or Hawaiian blue eyes, is flowering plant from the family Convolvulaceae that is native to Brazil, Guyana, Bolivia and Venezuela.',15.0,'https://upload.wikimedia.org/wikipedia/commons/a/a6/Evolvulus_glomeratus_%22Blue_Daze%22.jpg','flowering',1,10,0,'groundcover,blue,border','easy','full','moderate',1780014577977,1780016063204);
INSERT INTO Plant VALUES('cmpq6pz8h000fk6o6m2nc4gfd','Canna Lily','Lirio Canna','Canna or canna lily is a genus of flowering plants consisting of 10 species. It is the only genus in the family Cannaceae. All of the genus''s species are native to the American tropics and were naturalized in Europe, India and Africa in the 1860s. Although they grow native to the tropics, most cultivars have been developed in temperate climates and are easy to grow in most countries of the world, as long as they receive at least 6–8 hours average','Canna o lirio caña, caña de indias, achira, chisguas, bandera, o también bandera española en el español filipino, es un género de plantas con flores formado por 19 especies. Es el único género de la familia Cannaceae. Todas las especies son nativas de los trópicos americanos y se naturalizaron en Europa, India y África a partir de la década de 1860. La mayoría de los cultivares se han desarrollado en climas templados y son fáciles de mantener sie',25.0,'https://upload.wikimedia.org/wikipedia/commons/8/8a/Canna_sp.jpg','flowering',1,10,0,'bold,tropical,colorful','easy','full','moderate',1780014578850,1780016063206);
INSERT INTO Plant VALUES('cmpq6pzkn000gk6o6wxab8ozz','Confederate Jasmine','Jazmín Confederado','Trachelospermum jasminoides is a species of flowering plant in the family Apocynaceae, native to eastern and southeastern Asia. Common names include Confederate jasmine, star jasmine, Confederate jessamine, and Chinese star jessamine.','Trachelospermum jasminoides, llamada popularmente jazmín estrella, jazmin campanita, jazmín hélice, jazmin del aire o jazmín de leche, es una especie trepadora perteneciente al género Trachelospermum.',28.0,'https://upload.wikimedia.org/wikipedia/commons/9/92/Trachelospermum_jasminoides1215878198.jpg','flowering',1,10,0,'fragrant,climber,fence,white','easy','full','moderate',1780014579287,1780016063207);
INSERT INTO Plant VALUES('cmpq6pzwo000hk6o6wulrb4t6','Coral Honeysuckle','Madreselva Coral','Lonicera sempervirens is a flowering plant species of honeysuckle vine native to the eastern United States which is known for its reddish flowers.','Lonicera sempervirens is a flowering plant species of honeysuckle vine native to the eastern United States which is known for its reddish flowers.',22.0,'https://upload.wikimedia.org/wikipedia/commons/8/8b/Lonicera_sempervirens_2.jpg','flowering',1,10,0,'native,hummingbird,climber,red','easy','full','moderate',1780014579720,1780016063208);
INSERT INTO Plant VALUES('cmpq6q08p000ik6o6w7bxl2e0','Dwarf Bougainvillea','Buganvilla Enana','Bougainvillea is a genus of thorny ornamental vines, bushes, and trees belonging to the family Nyctaginaceae. They are native to the tropical forests of South America. There are between 4 and 22 species in the genus. The inflorescence consists of large colorful sepal-like bracts which surround three simple waxy flowers, gaining popularity for the plant as an ornamental. The plant is named after explorer Louis Antoine de Bougainville (1729–1811), ','El género Bougainvillea, conocido popularmente como veranera, papelillo, trinitaria, buganvilla, buganvilia,bugambilia, Santa Rita es un género de la familia Nyctaginaceae, con 18 especies aceptadas de las 35 descritas. Es nativo de los bosques tropicales húmedos de toda América del Sur, principalmente de los situados en áreas de Brasil, Perú, Paraguay, Bolivia, el norte de Argentina y Venezuela, Uruguay, ampliamente cultivado en regiones tropica',28.0,'https://upload.wikimedia.org/wikipedia/commons/4/4c/Bougainvillea_closeup.jpg','flowering',1,10,0,'compact,colorful,border,container','easy','full','low',1780014580153,1780016063209);
INSERT INTO Plant VALUES('cmpq6q0ku000jk6o6ti1d8b9o','Dwarf Ixora','Ixora Enana','Ixora coccinea is a species of flowering plant in the family Rubiaceae. It is a common flowering shrub native to Southern India, Bangladesh, and Sri Lanka. It has become one of the most popular flowering shrubs in South Florida gardens and landscapes. It is the national flower of Suriname.','Ixora coccinea, conocida como geranio de la jungla, llama de los bosques, coral, Cruz de Malta, coral de México y llama de la jungla, es una especie de arbusto perteneciente a la familia de las rubiáceas. Es la flor oficial de la ciudad de Cúcuta, en Colombia.',22.0,'https://upload.wikimedia.org/wikipedia/commons/7/77/Ixora_coccinea.jpg','flowering',1,10,0,'compact,border,hedge,red','easy','full','moderate',1780014580591,1780016063211);
INSERT INTO Plant VALUES('cmpq6q0wv000kk6o6fviwn4l5','Gardenia','Gardenia','Gardenia jasminoides, commonly known as gardenia and cape jasmine, is an evergreen flowering plant in the coffee family Rubiaceae. It is native to the subtropical and northern tropical parts of the Far East. Wild plants range from 30 centimetres to 3 metres in height. They have a rounded habit with very dense branches with opposite leaves that are lanceolate-oblong, leathery or gathered in groups on the same node and by a dark green, shiny and sl','El jazmín de la India o jazmín del Cabo es un árbol de hoja perenne perteneciente a la familia Rubiaceae. Tiene su origen en Asia y se encuentra en estado silvestre en Vietnam, el sur de China, Taiwán, Japón, Birmania y la India. Fue introducida por los españoles en América.',38.0,'https://upload.wikimedia.org/wikipedia/commons/5/54/Gardenia_jasminoides_flower_Argentina.jpg','flowering',1,10,0,'fragrant,white,classic','moderate','partial','moderate',1780014581024,1780016063212);
INSERT INTO Plant VALUES('cmpq6q18y000lk6o6srk4l67i','Hibiscus','Hibisco','Hibiscus × rosa-sinensis is a cultigen of tropical hibiscus, a flowering plant in the Hibiscus genus and Hibisceae tribe of the family Malvaceae.','Hibiscus rosa-sinensis, llamado comúnmente rosa de China, cayena,  amapola, hibisco, gumamela, entre otros nombres, es un arbusto perennifolio de la familia de las malváceas, originario de Asia oriental.',28.0,'https://upload.wikimedia.org/wikipedia/commons/2/21/Hibiscus_Brilliant.jpg','flowering',1,10,1,'tropical,colorful,hummingbird','easy','full','moderate',1780014581458,1780016063213);
INSERT INTO Plant VALUES('cmpq6q1ww000mk6o6tlyv4dhs','Jasmine','Jazmín','Jasminum sambac is a species of jasmine native to Bhutan and India. It is cultivated in many places, especially West Asia, South Asia and Southeast Asia. It is naturalised in many scattered locales: Mauritius, Madagascar, the Maldives, Christmas Island, Chiapas, Central America, southern Florida, the Bahamas, Cuba, Hispaniola, Jamaica, Puerto Rico, and the Lesser Antilles.','La Sampaguita es una flor típica de Filipinas, que actualmente forma como parte de un símbolo patrio de Filipinas junto con su escudo y bandera nacional. Considerada como una de las flores más bellas de Asia y el Pacífico, por su color blanco y tamaño pequeño. Esta flor crece en la zona montañosa de Pampanga, donde por lo general los niños y los campesinos van a recolectarlas a temprano horas de la mañana para ponerlas a la venta en los mercados ',28.0,'https://upload.wikimedia.org/wikipedia/commons/f/f3/Arabian_jasmin%2C_Tunisia_2010.jpg','flowering',1,10,0,'fragrant,classic,white','easy','partial','moderate',1780014582320,1780016063215);
INSERT INTO Plant VALUES('cmpq6q2ov000nk6o6thjdxyq3','Pentas','Pentas','Pentas lanceolata, commonly known as Egyptian starcluster, is a species of flowering plant in the madder family, Rubiaceae that is native to tropical Africa from Sudan to Democratic Republic of the Congo and Mozambique, as well as Saudi Arabia and Yemen on the Arabian Peninsula. It is sometimes planted in butterfly gardens.','Pentas lanceolata, commonly known as Egyptian starcluster, is a species of flowering plant in the madder family, Rubiaceae that is native to tropical Africa from Sudan to Democratic Republic of the Congo and Mozambique, as well as Saudi Arabia and Yemen on the Arabian Peninsula. It is sometimes planted in butterfly gardens.',15.0,'https://upload.wikimedia.org/wikipedia/commons/9/9a/Penta.JPG','flowering',1,10,0,'butterfly,hummingbird,colorful,year-round','easy','full','moderate',1780014583328,1780016063216);
INSERT INTO Plant VALUES('cmpq6q3d1000ok6o6pjbbusui','Portulaca','Portulaca','Portulaca grandiflora is a succulent flowering plant in the purslane family Portulacaceae, native to southern Brazil, Argentina, and Uruguay and often cultivated in gardens. It has many common names, including rose moss, eleven o''clock, Mexican rose, moss rose, sun rose, rose Jepun, table rose, rock rose, and moss-rose purslane. Despite these names and the superficial resemblance of some cultivars'' flowers to roses, it is not a true rose, nor eve','Portulaca grandiflora is a succulent flowering plant in the purslane family Portulacaceae, native to southern Brazil, Argentina, and Uruguay and often cultivated in gardens. It has many common names, including rose moss, eleven o''clock, Mexican rose, moss rose, sun rose, rose Jepun, table rose, rock rose, and moss-rose purslane. Despite these names and the superficial resemblance of some cultivars'' flowers to roses, it is not a true rose, nor eve',12.0,'https://upload.wikimedia.org/wikipedia/commons/9/98/PortulacaGrandiflora.jpg','flowering',1,10,0,'groundcover,colorful,drought-tolerant','easy','full','low',1780014584198,1780016063217);
INSERT INTO Plant VALUES('cmpq6q3p1000pk6o6qipyoa2o','Royal Poinciana','Framboyán','Royal Poinciana thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Framboyán prospera en el cálido y húmedo clima del sur de Florida.',125.0,'https://upload.wikimedia.org/wikipedia/commons/8/87/Royal_Poinciana.jpg','flowering',1,10,1,'tree,dramatic,red,iconic','easy','full','low',1780014584629,1780016063218);
INSERT INTO Plant VALUES('cmpq6q414000qk6o6r82k72g8','Salvia','Salvia','Salvia thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Salvia prospera en el cálido y húmedo clima del sur de Florida.',15.0,'https://upload.wikimedia.org/wikipedia/commons/5/5a/Salvia_officinalis0.jpg','flowering',1,10,0,'hummingbird,butterfly,herb','easy','full','moderate',1780014585064,1780016063220);
INSERT INTO Plant VALUES('cmpq6q4p6000rk6o6arfzg8lw','Thryallis','Triyalis','Galphimia gracilis, a species in the genus Galphimia of the family Malpighiaceae, is native to eastern Mexico. It is widely cultivated in warm regions throughout the world, often under the common names gold shower or shower-of-gold, slender goldshower or sometimes thryallis.','Galphimia gracilis, a species in the genus Galphimia of the family Malpighiaceae, is native to eastern Mexico. It is widely cultivated in warm regions throughout the world, often under the common names gold shower or shower-of-gold, slender goldshower or sometimes thryallis.',25.0,'https://upload.wikimedia.org/wikipedia/commons/7/78/Malphighia3.jpg','flowering',1,10,0,'yellow,butterfly,border,drought-tolerant','easy','full','low',1780014585930,1780016063222);
INSERT INTO Plant VALUES('cmpq6q516000sk6o6b964w2kb','Yellow Elder','Tronador Amarillo','Tecoma stans is a species of flowering perennial shrub in the trumpet vine family, Bignoniaceae, that is native to the Americas. Common names include yellow trumpetbush, yellow bells, yellow elder, ginger Thomas. Tecoma stans is the official flower of the United States Virgin Islands and the floral emblem of The Bahamas.','El tronador, huaranhuay, tronadora o timboque es un arbusto o árbol de la familia de las bignoniáceas, nativo del continente Americano. Se encuentra en gran variedad de Ambientes y en casi todos los continentes. Se cultiva como planta ornamental por sus vistosas flores amarillas. Tiene gran variedad de usos y más de 50 componentes químicos.',45.0,'https://upload.wikimedia.org/wikipedia/commons/d/db/Ip%C3%AA-de-jardim_%28do_tupi_%27yp%C3%A9%29%2C_Tecoma_stans%2C_em_Bag%C3%A9-RS%2C_Brasil.jpg','flowering',1,10,0,'tree,yellow,butterfly,native-like','easy','full','low',1780014586362,1780016063223);
INSERT INTO Plant VALUES('cmpq6q5db000tk6o6rxl0304a','African Tulip Tree','Árbol Tulipán Africano','Spathodea is a genus in the plant family Bignoniaceae. The single species it contains, Spathodea campanulata, is commonly known as the African tulip tree or the Nandi Flame. The tree grows between 7–25 m (23–82 ft) tall and is native to tropical dry forests of Africa. It has been nominated as among 100 of the "World''s Worst" invaders.','Spathodea es un género monotípico de fanerógamas perteneciente a la familia de las bignoniáceas. La única especie de este género, Spathodea campanulata, conocida como tulipero africano, tulipanero africano, árbol de la fontana, llama-del-bosque, llama Nandi, amapola, o meaíto y también caoba de Santo Domingo y gallito en Venezuela. En francés se denomina tulipier du Gabon. En México también se le conoce como galeana, o simplemente como (árbol) tu',85.0,'https://upload.wikimedia.org/wikipedia/commons/2/21/Starr_031210-0047_Spathodea_campanulata.jpg','tropical',1,10,0,'tree,dramatic,orange','easy','full','moderate',1780014586800,1780016063225);
INSERT INTO Plant VALUES('cmpq6q5pg000uk6o6d4ey0eez','Air Plant','Planta de Aire','Tillandsia is a genus of around 650 species of evergreen, perennial flowering plants in the family Bromeliaceae, native to the forests, mountains and deserts of the Neotropics, from northern Mexico and the southeastern United States to Mesoamerica and the Caribbean to central Argentina. Their leaves, more or less silvery in color, are covered with specialized cells (trichomes) capable of rapidly absorbing water that gathers on them.','Tillandsia es un género de plantas mayoritariamente epifitas que, con más de seiscientas cincuenta especies aceptadas, es el más diverso de la familia Bromeliaceae. Se encuentran en los desiertos, bosques y montañas de Centroamérica, Sudamérica, en México y el sur de Estados Unidos en Norteamérica.',18.0,'https://upload.wikimedia.org/wikipedia/commons/6/6a/Tillandsia_fasciculata.jpg','tropical',1,10,0,'epiphyte,no-soil,unique,display','easy','partial','low',1780014587237,1780016063226);
INSERT INTO Plant VALUES('cmpq6q61g000vk6o6ns2btwwq','Alpinia','Alpinia','Alpinia zerumbet, commonly known as shell ginger among other names, is a perennial species of ginger native to East Asia. The plants can grow up to 2.5 to 3 meters tall and bear colorful funnel-shaped flowers. They are grown as ornamentals and their leaves are used in cuisine and traditional medicine.','La azucena de porcelana es una especie de planta perenne de jengibre nativo de Asia Oriental. Pueden crecer hasta los 2,4 a 3,0 m de altura y produce coloridas flores en forma de embudo. Se cultivan como plantas ornamentales y sus hojas se usan en la cocina y la medicina tradicional.',35.0,'https://upload.wikimedia.org/wikipedia/commons/1/1e/200410_Alpinia_zerumbet_1.JPG','tropical',1,10,0,'ginger-family,tropical,fragrant','easy','partial','moderate',1780014587669,1780016063228);
INSERT INTO Plant VALUES('cmpq6q6di000wk6o62v3mp3iw','Anthurium','Anturio','Anthurium is a genus of about 1,000 species of flowering plants, the largest genus of the arum family, Araceae. General common names include anthurium, tailflower, flamingo flower, pigtail plant, and laceleaf.','El género neotropical Anthurium consta de 600 a 800 especies, llamadas comúnmente anturios. Inicialmente se descubrió en Costa Rica aunque es nativo de Colombia, Venezuela y Perú. Es originario de las zonas tropicales y subtropicales de América Central y América del Sur.',45.0,'https://upload.wikimedia.org/wikipedia/commons/7/75/Anthurium3.JPG','tropical',1,10,0,'tropical,indoor,flowering,red','moderate','shade','moderate',1780014588102,1780016063229);
INSERT INTO Plant VALUES('cmpq6q6pj000xk6o6645sw1bs','Banana Tree','Platanero','Banana Tree thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','El género Musa es el género tipo de la familia de las musáceas, que comprende una cincuentena de especies de megaforbas de confusa taxonomía, así como decenas de híbridos, entre los cuales se cuentan Musa acuminata, Musa balbisiana y Musa × paradisiaca, las tres especies comprendidas bajo el epíteto común de banano. Son grandes plantas herbáceas de origen asiático con un pseudotallo constituido a partir de las vainas foliares.',55.0,'https://upload.wikimedia.org/wikipedia/commons/d/de/Bananavarieties.jpg','tropical',1,10,1,'tropical,fast-growing,edible,dramatic','easy','full','high',1780014588535,1780016063231);
INSERT INTO Plant VALUES('cmpq6q7dk000yk6o6vuuov1nu','Bromeliad','Bromelia','The Bromeliaceae are a family of monocot flowering plants of about 80 genera and 3700 known species, native mainly to the tropical Americas, with several species found in the American subtropics and one in tropical west Africa, Pitcairnia feliciana.','The Bromeliaceae are a family of monocot flowering plants of about 80 genera and 3700 known species, native mainly to the tropical Americas, with several species found in the American subtropics and one in tropical west Africa, Pitcairnia feliciana.',25.0,'https://upload.wikimedia.org/wikipedia/commons/1/17/Pineapple1.JPG','tropical',1,10,0,'tropical,colorful,epiphyte,display','easy','partial','low',1780014589401,1780016063232);
INSERT INTO Plant VALUES('cmpq6q7pp000zk6o6zuaci9rp','Caladium','Caladio','Caladium is a genus of flowering plants in the family Araceae. They are often known by the common name elephant ear, heart of Jesus, and angel wings. There are over 1000 named cultivars of Caladium bicolor from the original South American plant.','Caladium is a genus of flowering plants in the family Araceae. They are often known by the common name elephant ear, heart of Jesus, and angel wings. There are over 1000 named cultivars of Caladium bicolor from the original South American plant.',28.0,'https://upload.wikimedia.org/wikipedia/commons/f/f1/Caladium_schomburgkii_changjur-1-yercaud-salem-India.JPG','tropical',1,10,0,'colorful,shade,foliage,seasonal','moderate','shade','moderate',1780014589837,1780016063233);
INSERT INTO Plant VALUES('cmpq6q81p0010k6o6xgfj8h4f','Calathea','Calatea','Calathea thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Calatea prospera en el cálido y húmedo clima del sur de Florida.',38.0,'https://images.unsplash.com/photo-1598880940371-c756e015fea1?auto=format&fit=crop&w=800&q=80','tropical',1,10,0,'patterned,indoor,tropical,bold','moderate','shade','high',1780014590269,1780015036422);
INSERT INTO Plant VALUES('cmpq6q8ds0011k6o6iu4xwgzx','Clusia','Clusia','Clusia thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Clusia prospera en el cálido y húmedo clima del sur de Florida.',45.0,'https://upload.wikimedia.org/wikipedia/commons/7/71/Clusia1.jpg','tropical',1,10,0,'hedge,salt-tolerant,coastal,thick','easy','partial','moderate',1780014590704,1780016063235);
INSERT INTO Plant VALUES('cmpq6q8re0012k6o6pwitjmrx','Costus','Costus','Costus thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Costus prospera en el cálido y húmedo clima del sur de Florida.',32.0,'https://images.unsplash.com/photo-1614594975525-e45190c55d0b?auto=format&fit=crop&w=800&q=80','tropical',1,10,0,'ginger-relative,tropical,flowering','easy','partial','moderate',1780014591194,1780015037831);
INSERT INTO Plant VALUES('cmpq6q9fe0013k6o6hv98i98b','Dieffenbachia','Diefenbaquia','Dieffenbachia thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Dieffenbachia es un género de plantas tropicales de la familia de las aráceas, notables por las características manchas claras en sus hojas. Se conocen cerca de 30 especies, algunas utilizadas como plantas de interior debido a su tolerancia a la sombra. La especie más cultivada es Dieffenbachia bowmanii.',35.0,'https://upload.wikimedia.org/wikipedia/commons/e/e0/Starr_061212-2331_Dieffenbachia_seguine.jpg','tropical',1,10,0,'indoor,tropical,large-leaf','moderate','shade','moderate',1780014592059,1780016063236);
INSERT INTO Plant VALUES('cmpq6q9rc0014k6o67zcs1l0a','Dracaena','Drácena','Dracaena reflexa is a tree native to Mozambique, Madagascar, Mauritius, and other nearby islands of the Indian Ocean. It is widely grown as an ornamental plant and houseplant, valued for its richly coloured, evergreen leaves, and thick, irregular stems.','La drácena, drácena marginata o dracaena de hoja fina, considerada un sinónimo de Dracaena reflexa var. angustifolia, es una especie fanerógama de la familia Asparagaceae, anteriormente incluida en Ruscaceae, originaria de Madagascar.',45.0,'https://upload.wikimedia.org/wikipedia/commons/6/61/Dracaena_reflexa.JPG','tropical',1,10,0,'indoor,drought-tolerant,architectural','easy','partial','low',1780014592489,1780016063237);
INSERT INTO Plant VALUES('cmpq6qafk0015k6o6p2glqfsk','Fiddle Leaf Fig','Ficus Lyrata','Ficus lyrata, commonly known as the fiddle-leaf fig, banjo fig, fiddle-leaved fig tree, lyre leaf fig tree, or lyre-leaved fig tree, is a species of plant in the mulberry and fig family Moraceae. It is native to western Africa, but is cultivated around the world as an ornamental plant. It has received the Royal Horticultural Society''s Award of Garden Merit.','Ficus lyrata, comúnmente conocido como higuera hoja de violín, es una especie de planta con flores perteneciente a la familia Moraceae. Es originaria de África Occidental, desde Camerún al oeste hasta Sierra Leona, donde crece en las tierras bajas de selva tropical.',85.0,'https://upload.wikimedia.org/wikipedia/commons/8/84/Starr_031108-0130_Ficus_lyrata.jpg','tropical',1,10,0,'indoor,statement,designer,large-leaf','moderate','partial','moderate',1780014593360,1780016063238);
INSERT INTO Plant VALUES('cmpq6qarm0016k6o6lqc4ogky','Frangipani','Plumeria','Plumeria, commonly known as frangipani, is a genus of flowering plants in the family Apocynaceae. Most species are deciduous shrubs or small trees. They are native to the Neotropical realm, but are often grown as ornamentals in tropical regions, especially in Hawaii, as well as hot desert climates in the Arabian Peninsula with irrigation.','Plumeria o Plumaria es un pequeño género de plantas nativas de las regiones tropicales y subtropicales de América. Comprende 133 especies descritas y de estas, solo 11 aceptadas. Las especies se han extendido por todas las regiones tropicales del mundo, especialmente en Hawái, donde se cultivan tan abundantemente que se consideran autóctonas.',55.0,'https://upload.wikimedia.org/wikipedia/commons/e/ed/Plumeria_rubra-4.JPG','tropical',1,10,0,'fragrant,tropical,lei,island','easy','full','low',1780014593795,1780016063240);
INSERT INTO Plant VALUES('cmpq6qb3v0017k6o6u0d4di22','Ginger','Jengibre Ornamental','Hedychium is a genus of flowering plants in the ginger family Zingiberaceae, native to lightly wooded habitats in Asia. There are approximately 70-80 known species, native to India, Southeast Asia, and Madagascar. Some species have become widely naturalized in other lands, and considered invasive in some places.','Hedychium es un género de plantas perennes nativas de Asia tropical y de los Himalayas, comúnmente alcanza 1,2 a 1,8 metros de altura. Algunas especies son ornamentales.Comprende 140 especies descritas y de estas, solo 87 aceptadas.',32.0,'https://upload.wikimedia.org/wikipedia/commons/3/32/Starr_020803-0036_Hedychium_coronarium.jpg','tropical',1,10,0,'fragrant,tropical,edible,large','easy','partial','moderate',1780014594236,1780016063241);
INSERT INTO Plant VALUES('cmpq6qbfu0018k6o6yca5sn55','Heliconia','Heliconia','Heliconia is a genus of flowering plants in the monotypic family Heliconiaceae. Most of the 194 known species are native to the tropical Americas, but a few are indigenous to certain islands of the western Pacific and Maluku in Indonesia. Many species of Heliconia are found in the tropical forests of these regions. Most species are listed as either vulnerable or data deficient by the IUCN Red List of threatened species. Several species are widely','Heliconia L. es un género que agrupa más de 100 especies de plantas tropicales, originarias de Sudamérica, Centroamérica, las islas del Pacífico e Indonesia. Se les llama platanillo por sus hojas o ave del paraíso y pinza de langosta por las coloridas brácteas que envuelven sus flores. Es el único género de la familia Heliconiaceae.',45.0,'https://upload.wikimedia.org/wikipedia/commons/2/23/Heliconia_latispatha_%28Starwiz%29.jpg','tropical',1,10,0,'tropical,dramatic,bird-attracting,bold','easy','full','high',1780014594667,1780016063242);
INSERT INTO Plant VALUES('cmpq6qbry0019k6o6xn5gvbg8','Jatropha','Jatrofa','Jatropha integerrima, commonly known as peregrina or spicy jatropha, is a species of flowering plant in the spurge family, Euphorbiaceae, that is native to Cuba and Hispaniola.','Jatropha integerrima, commonly known as peregrina or spicy jatropha, is a species of flowering plant in the spurge family, Euphorbiaceae, that is native to Cuba and Hispaniola.',38.0,'https://upload.wikimedia.org/wikipedia/commons/1/13/Jatropha_interregima.JPG','tropical',1,10,0,'butterfly,red,drought-tolerant','easy','full','low',1780014595102,1780016063244);
INSERT INTO Plant VALUES('cmpq6qc3z001ak6o64nvkxr9t','Liriope','Liriope','Liriope muscari is a species of flowering plant from East Asia. Common names in English include big blue lilyturf, lilyturf, border grass, and monkey grass. This small herbaceous perennial has grass-like evergreen foliage and lilac-purple flowers which produce single-seeded berries on a spike in the fall. In some parts of the United States, it is an invasive species.','Liriope muscari is a species of flowering plant from East Asia. Common names in English include big blue lilyturf, lilyturf, border grass, and monkey grass. This small herbaceous perennial has grass-like evergreen foliage and lilac-purple flowers which produce single-seeded berries on a spike in the fall. In some parts of the United States, it is an invasive species.',22.0,'https://upload.wikimedia.org/wikipedia/commons/5/56/Liriope_muscari_4.JPG','tropical',1,10,0,'groundcover,border,shade-tolerant,purple','easy','partial','moderate',1780014595535,1780016063245);
INSERT INTO Plant VALUES('cmpq6qcg4001bk6o6a04x4x6d','Monstera Deliciosa','Monstruo Delicioso','Monstera deliciosa, the Swiss cheese plant or split-leaf philodendron, is a species of flowering plant. The common name "Swiss cheese plant" is also used for the related species from the same genus, Monstera adansonii. The common name "split-leaf philodendron" is also used for the species Philodendron bipinnatifidum.','Monstera deliciosa, the Swiss cheese plant or split-leaf philodendron, is a species of flowering plant. The common name "Swiss cheese plant" is also used for the related species from the same genus, Monstera adansonii. The common name "split-leaf philodendron" is also used for the species Philodendron bipinnatifidum.',65.0,'https://upload.wikimedia.org/wikipedia/commons/2/2e/Monstera_deliciosa2.jpg','tropical',1,10,1,'trendy,indoor,large-leaf,bold','moderate','partial','moderate',1780014595972,1780016063247);
INSERT INTO Plant VALUES('cmpq6qcs8001ck6o6dj1tweul','Mussaenda','Mussaenda','Mussaenda is a genus of flowering plants in the family Rubiaceae. They are native to the African and Asian tropics and subtropics. Several species are cultivated as ornamental plants.','Mussaenda is a genus of flowering plants in the family Rubiaceae. They are native to the African and Asian tropics and subtropics. Several species are cultivated as ornamental plants.',45.0,'https://upload.wikimedia.org/wikipedia/commons/2/28/Mussaenda_frondosa.jpg','tropical',1,10,0,'colorful,tropical,showy','easy','full','moderate',1780014596408,1780016063248);
INSERT INTO Plant VALUES('cmpq6qd4r001dk6o6v1gdq2rm','Orchid','Orquídea','Orchids are plants that belong to the family Orchidaceae, a diverse and widespread group of flowering plants with blooms that are often colourful and fragrant. Orchids are cosmopolitan plants, living in diverse habitats on every continent except Antarctica. The world''s richest diversity of orchid genera and species is in the tropics. Many species are epiphytes, living on trees. The flowers and their pollination mechanisms are highly specialized, ','Orchids are plants that belong to the family Orchidaceae, a diverse and widespread group of flowering plants with blooms that are often colourful and fragrant. Orchids are cosmopolitan plants, living in diverse habitats on every continent except Antarctica. The world''s richest diversity of orchid genera and species is in the tropics. Many species are epiphytes, living on trees. The flowers and their pollination mechanisms are highly specialized, ',55.0,'https://upload.wikimedia.org/wikipedia/commons/3/34/Plant_Orchid_Cymbidium_aloifolium_P1110661_05_-_cropped.jpg','tropical',1,10,0,'elegant,exotic,indoor,flowering','expert','partial','moderate',1780014596859,1780016063249);
INSERT INTO Plant VALUES('cmpq6qdgs001ek6o64c1dvkxf','Peace Lily','Lirio de la Paz','Spathiphyllum is a genus of about 60 species of monocotyledonous flowering plants in the family Araceae, native to tropical regions of the Americas and southeastern Asia. Certain species of Spathiphyllum are commonly known as spath or peace lilies.','Spathiphyllum is a genus of about 60 species of monocotyledonous flowering plants in the family Araceae, native to tropical regions of the Americas and southeastern Asia. Certain species of Spathiphyllum are commonly known as spath or peace lilies.',38.0,'https://upload.wikimedia.org/wikipedia/commons/b/bd/Spathiphyllum_cochlearispathum_RTBG.jpg','tropical',1,10,0,'indoor,air-purifying,white,shade','easy','shade','moderate',1780014597292,1780016063250);
INSERT INTO Plant VALUES('cmpq6qdss001fk6o6xvikmyge','Philodendron','Filodendro','Philodendron is a large genus of flowering plants in the family Araceae. As of September 2025, the Plants of the World Online accepted 625 species; other sources accept different numbers. Regardless of number of species, the genus is the second-largest member of the family Araceae, after genus Anthurium. Taxonomically, the genus Philodendron is still poorly known, with many undescribed species. Many are grown as ornamental and indoor plants. The ','Philodendron is a large genus of flowering plants in the family Araceae. As of September 2025, the Plants of the World Online accepted 625 species; other sources accept different numbers. Regardless of number of species, the genus is the second-largest member of the family Araceae, after genus Anthurium. Taxonomically, the genus Philodendron is still poorly known, with many undescribed species. Many are grown as ornamental and indoor plants. The ',45.0,'https://upload.wikimedia.org/wikipedia/commons/8/8e/Philodendron_giganteum_-_Laeken_Royal_Greenhouses_-_Royal_Castle_of_Laeken_-_Brussels%2C_Belgium_-_DSC07236.jpg','tropical',1,10,0,'indoor,tropical,easy-care,climbing','easy','partial','moderate',1780014597725,1780016063252);
INSERT INTO Plant VALUES('cmpq6qe4s001gk6o6gwi1bxfm','Podocarpus','Podocarpus','Podocarpus thrives in South Florida''s warm, humid climate and is an excellent addition to Miami gardens.','Podocarpus prospera en el cálido y húmedo clima del sur de Florida.',45.0,'https://upload.wikimedia.org/wikipedia/commons/c/cf/PodocarpusTotara2.jpg','tropical',1,10,0,'hedge,formal,privacy,slow-growing','easy','partial','moderate',1780014598157,1780016063253);
INSERT INTO Plant VALUES('cmpq6qegy001hk6o6hcgtyc33','Pothos','Potus','Epipremnum aureum is a species in the arum family Araceae, native to Mo''orea in the Society Islands of French Polynesia. The species is a popular houseplant in temperate regions, but has also become naturalised in tropical and sub-tropical forests worldwide, including northern South Africa, Australia, Southeast Asia, Indian subcontinent, the Pacific Islands and the West Indies, where it has caused severe ecological damage in some cases.','Epipremnum aureum, comúnmente conocido como potus, pothos o poto es una especie de la familia Araceae nativa del sudeste asiático y Nueva Guinea. En ocasiones es confundida con philodendron en las floristerías.',22.0,'https://upload.wikimedia.org/wikipedia/commons/6/62/Money_Plant_%28Epipremnum_aureum%29_4.jpg','tropical',1,10,0,'indoor,trailing,easy-care,air-purifying','easy','partial','moderate',1780014598595,1780016063254);
INSERT INTO Plant VALUES('cmpq6qet0001ik6o6mmxq51ui','Rubber Plant','Árbol del Caucho','Ficus elastica, the rubber fig, rubber bush, rubber tree, rubber plant, or Indian rubber bush, Indian rubber tree, or rambung is a species of flowering plant in the family Moraceae, native to eastern parts of South and Southeast Asia. It has become naturalized in Sri Lanka, the West Indies, and the US state of Florida. Its common names reflect its historical use as a source of rubber within its native range, but it is not used in the modern comme','Ficus elastica, llamado comúnmente árbol del caucho gomero o caucho sabanero, es una especie perennifolia del género Ficus nativa del nordeste de India (Assam), oeste de Indonesia. Fue introducida en Europa en 1815 como planta de interior.',55.0,'https://upload.wikimedia.org/wikipedia/commons/1/16/Ficus_elastica_leaves_02.JPG','tropical',1,10,0,'indoor,bold,glossy,large-leaf','moderate','partial','moderate',1780014599028,1780016063256);
INSERT INTO Plant VALUES('cmpq6qf4x001jk6o6uvieqqx1','Schefflera','Schefflera','Schefflera is a genus of flowering plants in the family Araliaceae with 13 species native to New Zealand and some Pacific islands.','Schefflera es un género perteneciente a la familia Araliaceae. Son árboles, arbustos o lianas nativos de Nueva Zelanda, Java, India, Asia oriental y Fiyi.',45.0,'https://upload.wikimedia.org/wikipedia/commons/b/bc/Schefflera_digitata_258334362.jpg','tropical',1,10,0,'umbrella-tree,indoor,tropical','easy','partial','moderate',1780014599458,1780016063257);
INSERT INTO Plant VALUES('cmpq6qfgy001kk6o6ldjj3heh','Snake Plant','Planta Serpiente','Dracaena trifasciata is a species of flowering plant in the family Asparagaceae, native to tropical West Africa from Nigeria east to the Congo. It is most commonly known as the snake plant, Saint George''s sword, mother-in-law''s tongue, and viper''s bowstring hemp, among other names. Until 2017, it was known under the synonym Sansevieria trifasciata. This plant is often kept as a houseplant due to its non-demanding maintenance; they can survive wit','Dracaena trifasciata is a species of flowering plant in the family Asparagaceae, native to tropical West Africa from Nigeria east to the Congo. It is most commonly known as the snake plant, Saint George''s sword, mother-in-law''s tongue, and viper''s bowstring hemp, among other names. Until 2017, it was known under the synonym Sansevieria trifasciata. This plant is often kept as a houseplant due to its non-demanding maintenance; they can survive wit',38.0,'https://upload.wikimedia.org/wikipedia/commons/f/fb/Snake_Plant_%28Sansevieria_trifasciata_%27Laurentii%27%29.jpg','tropical',1,10,1,'indoor,architectural,air-purifying,drought-tolerant','easy','partial','low',1780014599890,1780016063258);
INSERT INTO Plant VALUES('cmpq6qg5m001lk6o6agja14w3','Strelitzia','Ave del Paraíso Blanca','Strelitzia nicolai, commonly known as the wild banana or giant white bird of paradise, is a species of banana-like plants with erect woody stems reaching a height of 7–8 m (23–26 ft), and the clumps formed can spread as far as 3.5 m (11 ft).','Strelitzia nicolai, llamada a veces Ave del paraíso gigante, es una planta angiosperma típica de las áreas tropicales y subtropicales, perteneciente a la familia Strelitziaceae.',85.0,'https://upload.wikimedia.org/wikipedia/commons/b/ba/Strelitzia_nicolai_3.jpg','tropical',1,10,0,'statement,tropical,architectural,large','easy','full','moderate',1780014600779,1780016063260);
INSERT INTO Plant VALUES('cmpq6qgi6001mk6o66kn5wfpr','Sweet Potato Vine','Batata Ornamental','The sweet potato or sweetpotato is a dicotyledonous plant in the morning glory family, Convolvulaceae. Its sizeable, starchy, sweet-tasting tuberous roots are used as a root vegetable, which is a staple food in parts of the world. Cultivars of the sweet potato have been bred to bear tubers with flesh and skin of various colors. Moreover, the young shoots and leaves are occasionally eaten as greens. The sweet potato and the potato are only distant','Ipomoea batatas, llamada comúnmente batata, chaco, papa dulce, patata dulce, papa camote, camote, moniato, boniato, o apichu, es una planta de la familia Convolvulaceae, cultivada en gran parte del mundo por su raíz tuberosa comestible, de sabor dulce.',15.0,'https://upload.wikimedia.org/wikipedia/commons/5/58/Ipomoea_batatas_006.JPG','tropical',1,10,0,'groundcover,colorful,fast-growing,container','easy','full','moderate',1780014601231,1780016063261);
INSERT INTO Plant VALUES('cmpq6qhls001nk6o6kqwv1o6n','Variegated Ginger','Jengibre Variegado','Alpinia zerumbet, commonly known as shell ginger among other names, is a perennial species of ginger native to East Asia. The plants can grow up to 2.5 to 3 meters tall and bear colorful funnel-shaped flowers. They are grown as ornamentals and their leaves are used in cuisine and traditional medicine.','La azucena de porcelana es una especie de planta perenne de jengibre nativo de Asia Oriental. Pueden crecer hasta los 2,4 a 3,0 m de altura y produce coloridas flores en forma de embudo. Se cultivan como plantas ornamentales y sus hojas se usan en la cocina y la medicina tradicional.',38.0,'https://upload.wikimedia.org/wikipedia/commons/1/1e/200410_Alpinia_zerumbet_1.JPG','tropical',1,10,0,'variegated,tropical,ginger-family,bold','easy','partial','moderate',1780014602656,1780016063263);
INSERT INTO Plant VALUES('cmpq6qhyd001ok6o6zjqt50wj','ZZ Plant','Planta ZZ','Zamioculcas is a genus of flowering plants in the family Araceae, containing the single species Zamioculcas zamiifolia. It is a tropical herbaceous perennial plant, and is native to eastern Africa, including Kenya, KwaZulu-Natal, Malawi, Mozambique, Tanzania, and Zimbabwe. Its common names include Zanzibar gem, Zuzu plant, emerald palm, ZZ plant, aroid palm and eternity plant. It is commonly grown as a houseplant, mainly because it has attractive','Zamioculcas es un género monotípico de plantas con flores perteneciente a la familia Araceae. Su única especie, Zamioculcas zamiifolia (Lodd.) Engl.. es una planta tropical nativa de África oriental, desde el sur de Kenia hasta el nordeste de Sudáfrica.',55.0,'https://upload.wikimedia.org/wikipedia/commons/c/cf/Zamioculcas_zamiifolia_1.jpg','tropical',1,10,0,'indoor,drought-tolerant,glossy,easy-care','easy','shade','low',1780014603109,1780016063264);
INSERT INTO Plant VALUES('cmpq6qig2001pk6o6308n75uc','Buttonwood','Botoncillo','Conocarpus erectus, commonly called buttonwood or button mangrove, is a hardy species of mangrove shrub in the family Combretaceae.','El mangle botoncillo o mangle zaragoza es un árbol de la familia Combretaceae que crece en las costas, en las regiones tropicales y subtropicales de todo el mundo, incluyendo Florida, las Bermudas, las Bahamas, el Caribe, Centroamérica y desde el sur de México hasta Brasil en la costa atlántica y de México a Ecuador en la costa del Pacífico, así como en África occidental, Melanesia y Polinesia. Es una de las dos especies de mangles pertenecientes',55.0,'https://upload.wikimedia.org/wikipedia/commons/3/3d/Conocarpus_erectus_Key_Largo.jpg','native',1,10,0,'native,coastal,salt-tolerant,hedge','easy','full','low',1780014603746,1780016063265);
INSERT INTO Plant VALUES('cmpq6qiva001qk6o6zxf57oou','Fakahatchee Grass','Hierba Fakahatchee','Tripsacum dactyloides, commonly called eastern gamagrass, or Fakahatchee grass, is a warm-season, sod-forming bunch grass. It is widespread in the Western Hemisphere, native from the eastern United States to northern South America. Its natural habitat is in sunny moist areas, such as along watercourses and in wet prairies. In some areas, it has adapted well to disturbed conditions.','Tripsacum dactyloides, commonly called eastern gamagrass, or Fakahatchee grass, is a warm-season, sod-forming bunch grass. It is widespread in the Western Hemisphere, native from the eastern United States to northern South America. Its natural habitat is in sunny moist areas, such as along watercourses and in wet prairies. In some areas, it has adapted well to disturbed conditions.',22.0,'https://upload.wikimedia.org/wikipedia/commons/e/e9/Tripsacum_dactyloides_Arkansas.jpg','native',1,10,0,'native,ornamental-grass,wildlife','easy','full','moderate',1780014604295,1780016063266);
INSERT INTO Plant VALUES('cmpq6qjyt001rk6o61qzhb9fr','Mangrove','Mangle','Rhizophora mangle, also known as the red mangrove, is a salt-tolerant, small-to-medium sized evergreen tree restricted to coastal, estuarine ecosystems along the southern portions of North America, the Caribbean as well as Central America and tropical West Africa. Its viviparous "seeds", in actuality called propagules, become fully mature plants before dropping off the parent tree. These are dispersed by water until eventually embedding in the sh','Rhizophora mangle llamado comúnmente mangle rojo es una especie vegetal de la familia Rhizophoraceae, la cual cuenta con alrededor de 120 especies distribuidas en 16 géneros, siendo el género Rhizophora el más conocido, dominando las partes más anegadas de los ecosistemas manglar y la zona intermareal. Es una especie adaptada a ambientes salinos y tolera mayor salinidad que los otros mangles y sirve de refugio a animales terrestres y acuáticos. E',45.0,'https://upload.wikimedia.org/wikipedia/commons/a/a3/Rhizophora_mangle00.jpg','native',1,10,0,'native,coastal,ecological,water-edge','moderate','full','high',1780014605718,1780016063267);
INSERT INTO Plant VALUES('cmpq6qkf6001sk6o6sckl274r','Muhly Grass','Hierba Muhly','Muhlenbergia capillaris, commonly known as the hairawn muhly, is a perennial sedge-like plant that grows to be about 30–90 cm (0.98–2.95 ft) tall and 60–90 cm (2.0–3.0 ft) wide. The plant includes a double layer; green, leaf-like structures surround the understory, and purple-pink flowers outgrow them from the bottom up. The plant is a warm-season grass, meaning that leaves begin growth in the summer. During the summer, the leaves stay green, but','Muhlenbergia capillaris, commonly known as the hairawn muhly, is a perennial sedge-like plant that grows to be about 30–90 cm (0.98–2.95 ft) tall and 60–90 cm (2.0–3.0 ft) wide. The plant includes a double layer; green, leaf-like structures surround the understory, and purple-pink flowers outgrow them from the bottom up. The plant is a warm-season grass, meaning that leaves begin growth in the summer. During the summer, the leaves stay green, but',22.0,'https://upload.wikimedia.org/wikipedia/commons/d/d6/Muhlenbergia_capillaris_001.jpg','native',1,10,0,'native,ornamental-grass,pink,fall-color','easy','full','low',1780014606307,1780016063269);
INSERT INTO Plant VALUES('cmpq6qkv6001tk6o6ne9xsjhb','Saw Palmetto','Palma Serrada','Serenoa repens, commonly known as saw palmetto, is a small palm, growing to a maximum height around 200–300 cm (6.6–9.8 ft).','Serenoa repens, commonly known as saw palmetto, is a small palm, growing to a maximum height around 200–300 cm (6.6–9.8 ft).',55.0,'https://upload.wikimedia.org/wikipedia/commons/5/56/Serenoa_repens_USDA1.jpg','native',1,10,0,'native,wildlife,drought-tolerant,florida','easy','full','low',1780014606882,1780016063270);
INSERT INTO Plant VALUES('cmpq6ql7a001uk6o6vxek95c0','Sea Grape','Uva de Mar','Coccoloba uvifera is a species of tree and flowering plant in the buckwheat family, Polygonaceae. Its common names include seagrape and baygrape. It is native to coastal beaches throughout tropical America and the Caribbean. It has edible fruit, among other uses.','Coccoloba uvifera is a species of tree and flowering plant in the buckwheat family, Polygonaceae. Its common names include seagrape and baygrape. It is native to coastal beaches throughout tropical America and the Caribbean. It has edible fruit, among other uses.',55.0,'https://upload.wikimedia.org/wikipedia/commons/c/c4/Starr_080604-6302_Coccoloba_uvifera.jpg','native',1,10,0,'native,coastal,edible,salt-tolerant','easy','full','low',1780014607318,1780016063271);
INSERT INTO Plant VALUES('cmpq6qlje001vk6o6ctlx6idp','Avocado Tree','Aguacate','The avocado, alligator pear or avocado pear is an evergreen tree in the laurel family (Lauraceae). It is native to the Americas, with archaeological evidence of early human avocado use dating back thousands of years across various regions of Central and South America. It was prized for its large and unusually oily fruit. The native range of avocado extends from Mexico to Peru, encompassing much of Central America and parts of northern and western','The avocado, alligator pear or avocado pear is an evergreen tree in the laurel family (Lauraceae). It is native to the Americas, with archaeological evidence of early human avocado use dating back thousands of years across various regions of Central and South America. It was prized for its large and unusually oily fruit. The native range of avocado extends from Mexico to Peru, encompassing much of Central America and parts of northern and western',89.0,'https://upload.wikimedia.org/wikipedia/commons/f/f2/Persea_americana_fruit_2.JPG','edible',1,10,1,'edible,fruit,shade,backyard','easy','full','moderate',1780014607754,1780016063272);
INSERT INTO Plant VALUES('cmpq6qlvs001wk6o6gkdqfcsz','Lemon Tree','Limonero','The lemon is a species of small evergreen tree in the Citrus genus of the flowering plant family Rutaceae. A true lemon is a hybrid of the citron and the bitter orange. Its origins are uncertain, but some evidence suggests lemons originated during the 1st millennium BC in what is now northeastern India. Some other citrus fruits are called lemon.','The lemon is a species of small evergreen tree in the Citrus genus of the flowering plant family Rutaceae. A true lemon is a hybrid of the citron and the bitter orange. Its origins are uncertain, but some evidence suggests lemons originated during the 1st millennium BC in what is now northeastern India. Some other citrus fruits are called lemon.',65.0,'https://upload.wikimedia.org/wikipedia/commons/e/e4/P1030323.JPG','edible',1,10,1,'edible,container,fragrant,fruit','moderate','full','moderate',1780014608200,1780016063274);
INSERT INTO Plant VALUES('cmpq6qm7s001xk6o6fwsla1pu','Lime Tree','Limero','A lime is the fruit of several species of citrus, most of which are hybrids within the genus Citrus. Limes are generally small, round to oval fruits with green flesh and skin and a distinctly sour taste due to their high citric acid content. They are widely cultivated in tropical and subtropical regions for culinary, medicinal, and ornamental purposes.','Lima es un nombre genérico por el que se conocen varias frutas cítricas similares entre sí, de diversas especies de árboles frutales. A menudo se refiere a la lima ácida, llamada «limón» en las islas del Caribe, Centroamérica, Colombia, Ecuador, México, Perú y Venezuela. En cambio, en España y el Cono Sur, «limón» se refiere al grande y amarillo y «lima» al pequeño y verde. Lo mismo ocurre en inglés, francés y en la mayoría de idiomas. Esta disti',65.0,'https://upload.wikimedia.org/wikipedia/commons/8/8b/Lime_Blossom.jpg','edible',1,10,0,'edible,container,fragrant,fruit','moderate','full','moderate',1780014608633,1780016063275);
INSERT INTO Plant VALUES('cmpq6qmjy001yk6o6hkmv6mxa','Mango Tree','Mango','A mango is an edible stone fruit produced by the tropical tree Mangifera indica. It originated in the northeastern part of the Indian subcontinent, in what is now Bangladesh, northeastern India and Myanmar. M. indica has been cultivated in South and Southeast Asia since ancient times, resulting in two modern mango cultivar lineages: the "Indian" and the "Southeast Asian" types. Other species in the genus Mangifera also produce edible fruits calle','Mangifera indica, comúnmente mango o melocotón de los trópicos[cita requerida], es una especie arbórea frutal perteneciente a la familia Anacardiaceae.',95.0,'https://upload.wikimedia.org/wikipedia/commons/7/74/Mangos_-_single_and_halved.jpg','edible',1,10,1,'edible,shade,tropical,fruit','easy','full','moderate',1780014609070,1780016063277);
INSERT INTO Plant VALUES('cmpq6qn01001zk6o62p5r0hw9','Orange Tree','Naranjo','The orange, also called sweet orange to distinguish it from the bitter orange, is the fruit of a tree in the family Rutaceae. Botanically, this is the hybrid Citrus × sinensis, between the pomelo and the mandarin orange. The chloroplast genome, and therefore the maternal line, is that of pomelo. Hybrids of the sweet orange form later types of mandarin and the grapefruit. The sweet orange has had its full genome sequenced.','Naranja puede referirse a:Citrus × sinensis, el naranjo dulce, un árbol frutal.',65.0,'https://upload.wikimedia.org/wikipedia/commons/e/e3/Oranges_-_whole-halved-segment.jpg','edible',1,10,0,'edible,fragrant,fruit,container','moderate','full','moderate',1780014609649,1780016063278);
INSERT INTO Plant VALUES('cmpq6qncb0020k6o685cdq6no','Papaya','Papaya','The papaya, papaw, or pawpaw is the plant species Carica papaya, one of the 21 accepted species in the genus Carica of the family Caricaceae. Papaya, papaw and pawpaw are also the names of its fruit. It was first domesticated in Mesoamerica, within modern-day southern Mexico and Central America. It is grown in several countries in regions with a tropical climate. In 2024, India was the leading producer, accounting for 36% of the world total.','Carica papaya es la papaya herbácea del género Carica en la familia Caricaceae. Su fruto se conoce comúnmente como papaya, papayón, fruta bomba, olocotón, papayo, mamón o lechosa.[cita requerida]',35.0,'https://upload.wikimedia.org/wikipedia/commons/8/84/Carica_papaya_-_K%C3%B6hler%E2%80%93s_Medizinal-Pflanzen-029.jpg','edible',1,10,0,'edible,fast-growing,tropical,fruit','easy','full','high',1780014610092,1780016063280);
INSERT INTO Plant VALUES('cmpq6qnod0021k6o6qhjy9r52','Adenium','Rosa del Desierto','Adenium obesum, more commonly known as a desert rose, is a poisonous species of flowering plant belonging to the tribe Nerieae of the subfamily Apocynoideae of the dogbane family, Apocynaceae. It is native to the Sahel regions south of the Sahara, tropical and subtropical eastern and southern Africa, as well as the Arabian Peninsula. Other names for the flower include Sabi star, kudu, mock azalea, and impala lily. Adenium obesum is a popular hous','Adenium obesum es una especie de arbusto perteneciente a la familia Apocynaceae. Es también conocida como sabi star, kudu, rosa de invierno o rosa del desierto. Es nativa del este y sur tropical y subtropical de África y Arabia.',38.0,'https://upload.wikimedia.org/wikipedia/commons/4/4a/Adenium_Obesum_Flower_Side_Macro_Mar22_D72_23052-58_ZS_P.jpg','succulents',1,10,0,'succulent,flowering,drought-tolerant,container','moderate','full','low',1780014610526,1780016063281);
INSERT INTO Plant VALUES('cmpq6qo0f0022k6o6jn5v1muv','Aloe Vera','Aloe Vera','Aloe vera is a succulent plant species of the genus Aloe. It is widely distributed, and is considered an invasive species in many world regions.','Aloe vera, también llamada sábila, aloe o aloe vera, es una especie suculenta de la familia Asphodelaceae. Con unas quinientas (500) especies, el género Aloe está ampliamente distribuido y la especie más conocida, Aloe vera, se considera una planta medicinal y es utilizada así en muchas regiones del mundo. Se utiliza principalmente en la medicina tradicional de dos formas: el exudado de la hoja (alcíbar) se utiliza como laxante y el gel mucilagin',25.0,'https://upload.wikimedia.org/wikipedia/commons/4/4b/Aloe_vera_flower_inset.png','succulents',1,10,1,'medicinal,succulent,drought-tolerant,useful','easy','full','low',1780014610959,1780016063282);
INSERT INTO Plant VALUES('cmpq6qoco0023k6o6dw7eg72b','Crown of Thorns','Corona de Espinas','Euphorbia milii, the crown-of-thorns, Christ plant or Christ''s thorn, is a species of flowering plant in the spurge family, Euphorbiaceae, native to Madagascar. The specifies commemorates Baron Milius, once Governor of Réunion, who introduced the species to France in 1821.','La corona de Cristo es una planta fanerógama del género Euphorbia. Es un arbusto espinoso que puede alcanzar los 150 cm de altura.',22.0,'https://upload.wikimedia.org/wikipedia/commons/7/77/Euphorbia_Milii_flowers.jpg','succulents',1,10,0,'succulent,flowering,drought-tolerant,fence','easy','full','low',1780014611401,1780016063284);
INSERT INTO Plant VALUES('cmpq6qooq0024k6o6gf9y4vog','Echeveria','Echeveria','Echeveria is a large genus of flowering plants in the family Crassulaceae, native to semi-desert areas of Central America, Mexico and northwestern South America.','Echeveria es un género polifilético de plantas de la familia Crassulaceae. Cuenta con 293 especies que se distribuyen en zonas áridas, semiáridas y templadas del suroeste de Estados Unidos, México, Centroamérica y hasta el norte de Argentina.',18.0,'https://upload.wikimedia.org/wikipedia/commons/8/85/Echeveria_elegans_-_1.jpg','succulents',1,10,0,'succulent,rosette,drought-tolerant,container','easy','full','low',1780014611834,1780016063285);
INSERT INTO Plant VALUES('cmpq6qp0q0025k6o6jp91r9bb','Sedum','Sedum','Sedum is a large genus of flowering plants in the family Crassulaceae, members of which are commonly known as stonecrops. The genus has been described as containing up to 600 species, subsequently reduced to 400–500. They are leaf succulents found primarily in the Northern Hemisphere, but extending into the southern hemisphere in Africa and South America. The plants vary from annual and creeping herbs to shrubs. The plants have water-storing leav','Sedum es un género de plantas suculentas de la familia Crassulaceae que comprende unas 400 especies aceptadas, de las más de 1300 descritas.',18.0,'https://upload.wikimedia.org/wikipedia/commons/1/1c/Sedum_acre_single_-_Niitv%C3%A4lja.jpg','succulents',1,10,0,'succulent,groundcover,drought-tolerant,container','easy','full','low',1780014612266,1780016063286);
