INSERT INTO Testimonial VALUES('cmplo6rjv000lfjdmtus254mw','Jennifer M.','Pinecrest, FL',5,'Maytee completely transformed our backyard into a tropical paradise. She saved plants we thought were dead and created something magical. She''s the plant whisperer!','Maytee transformó completamente nuestro patio trasero en un paraíso tropical. ¡Salvó plantas que creíamos muertas y creó algo mágico!',NULL,1,1779741584635);
INSERT INTO Testimonial VALUES('cmplo6rjw000mfjdmoyp2iap3','Roberto & Ana G.','Coral Gables, FL',5,'We''ve used Maytee for three different properties now. Her eye for design, knowledge of Miami''s climate, and passion for plants is unmatched in South Florida.','Hemos usado a Maytee para tres propiedades diferentes. Su ojo para el diseño y conocimiento del clima de Miami no tiene igual en el sur de Florida.',NULL,1,1779741584636);
INSERT INTO Testimonial VALUES('cmplo6rjx000nfjdmpqejtv2r','Linda T.','Kendall, FL',5,'I called Maytee thinking my garden was beyond saving. Two visits later, it looks better than when we first planted it. She''s a miracle worker with plants.','Llamé a Maytee pensando que mi jardín no tenía solución. Después de dos visitas, luce mejor que cuando lo plantamos por primera vez.',NULL,1,1779741584637);
INSERT INTO Testimonial VALUES('cmplo6rjy000ofjdm2pfyd9t4','Carlos & Sofia R.','Doral, FL',5,'Our HOA actually gave us a compliment for once because of Maytee''s work! The front yard design she created is beautiful and incredibly low-maintenance.','¡Nuestra HOA nos dio un cumplido por primera vez gracias al trabajo de Maytee! El diseño del patio delantero es hermoso e increíblemente fácil de mantener.',NULL,0,1779741584639);
INSERT INTO Testimonial VALUES('cmplo6rjz000pfjdmwpr5kc0t','Patricia W.','Miami Lakes, FL',5,'Maytee is featured on TV for a reason — her knowledge is encyclopedic and her designs are stunning. Our pool area is now the envy of the neighborhood.','Maytee aparece en televisión por una razón: su conocimiento es enciclopédico y sus diseños son impresionantes.',NULL,1,1779741584640);
